<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>定时任务</span><el-button type="primary" size="small" @click="showDialog=true">新增任务</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="任务名称"/><el-table-column prop="command" label="命令" show-overflow-tooltip/><el-table-column prop="cron_expression" label="Cron表达式" width="150"/><el-table-column prop="last_run_at" label="上次执行" width="170"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'" size="small">{{row.status===1?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="success" @click="run(row)">执行</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="showDialog" :title="form.id?'编辑任务':'新增任务'" width="600px"><el-form :model="form" label-width="100px"><el-form-item label="任务名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="执行命令"><el-input v-model="form.command" type="textarea" :rows="2"/></el-form-item><el-form-item label="Cron表达式"><el-input v-model="form.cron_expression" placeholder="如：*/5 * * * *"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({id:null,name:'',command:'',cron_expression:'',status:1});const loadList=async()=>{const res=await request({url:'/admin/crontabs'});list.value=res.data?.list||[]};const edit=(row)=>{Object.assign(form,row);showDialog.value=true};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/admin/crontabs/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};const run=async(row)=>{await request({url:`/admin/crontabs/${row.id}/run`,method:'post'});ElMessage.success('任务已执行');loadList()};const submit=async()=>{if(form.id)await request({url:`/admin/crontabs/${form.id}`,method:'put',data:form});else await request({url:'/admin/crontabs',method:'post',data:form});ElMessage.success('保存成功');showDialog.value=false;loadList()};onMounted(()=>loadList())</script>
